"""Unit18 original overview based on printed pages52-57."""
from gen_overview import gen_sheet, box

def sheet(unit, content):
    col = '#A63C70'
    bg = '#FFE4F0'
    pictures = '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:20px">' + ''.join(('<figure style="margin:0;min-width:0">' + content.picture(w, 280) + f'<figcaption style="font-weight:700;margin-top:8px">{w}</figcaption></figure>' for w in content.CORE)) + '</div>'

    def lesson(n, title, pg, head, body):
        return dict(n=n, title=title, pg=pg, head=head, body=body, col=col, bg=bg, dk='#702344')
    lessons = [lesson(1, 'Nơi em muốn tham quan', '52–53', 'Where do you want to visit?', lambda c: box(bg, '<b>I want to visit Ha Noi Opera House.</b><br><b>Dragon Bridge</b>: Cầu Rồng · <b>Ngo Mon Square</b>: Quảng trường Ngọ Môn · <b>Ho Chi Minh City Museum</b>: Bảo tàng Thành phố Hồ Chí Minh.') + box(bg, '<b>Want to + visit + nơi đến.</b> Không viết want visit hoặc visit to.<br>Museum: bảo tàng · square: quảng trường · bridge: cầu. Tên địa danh có chữ và audio để em học, không phải đoán từ tranh chung.')), lesson(2, 'Hỏi cách đến nơi', '54–55', 'How can I get to…? — You can get there…', lambda c: pictures + box(bg, '<b>How can I get to Dragon Bridge?</b><br><b>You can get there by bicycle.</b><br><b>By bus / by bicycle / by taxi</b>; riêng đi bộ là <b>on foot</b>. Không dùng by foot hoặc by a bus.') + box(bg, '<b>Can + get</b>, không can gets/can to get.<br><b>Excuse me! I am lost.</b> — Xin lỗi, mình bị lạc.<br><b>Thank you so much!</b> — You are welcome.<br>Đọc thẻ đang làm: cùng nơi đến, hai bạn có thể dùng phương tiện khác nhau.')), lesson(3, 'Ngữ điệu, đọc và viết kế hoạch', '56–57', 'Câu hỏi Yes/No thường lên giọng.', lambda c: box(bg, '<b>Is it time for a trip? ↗</b><br><b>Is it far from here? ↗</b><br>Phần đọc có <b>by train / by ferry / on foot</b>; phần luyện có <b>by boat</b>. Phân biệt từng chặng: firstly/next/then/finally.') + box(bg, '<b>Thẻ tự soạn:</b> Nam · Dragon Bridge · by bus.<br><b>I want to visit Dragon Bridge. You can get there by bus.</b><br>Tự kiểm tra: đã có to trước visit chưa? Can + get? By phương tiện hay on foot? Đúng người và đúng chặng chưa? Lộ trình giả định phục vụ học tiếng Anh.'))]
    return gen_sheet(18, 'MEANS OF TRANSPORT', 'Unit18 · Global Success5 · Tập hai · Trang52–57', col, bg, lessons, ['Nơi muốn đến', 'Cách đi và phương tiện', 'Đọc, nghe và viết'], 'Mỗi chuyến đi mở thêm một điều em biết.', 'Học từ, nghe chậm, ABC và hội thoại; sáu đề theo ba cấp độ.', 'Nội dung tự soạn, bám Unit18 · Global Success5, tập hai')
